from __future__ import print_function
from __future__ import absolute_import
from builtins import object
from subprocess import CalledProcessError
import re
from taf.ul.trs_e2e_fw.lib.ipsec.command_builder import CommandBuilder
from taf.ul.trs_e2e_fw.lib.ipsec.exceptions import IpSecDisabledError
from taf.ul.trs_e2e_fw.lib.utils import resource_file
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.ipsec.ipsec_secgw import ipsec_secgw
from taf.ul.trs_e2e_fw.lib.ipsec.ipsec_utils import ipsec_utils
from taf.ul.trs_e2e_fw.lib.ipsec.ipsec_validate import ipsec_validate
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.ipsec.generate_esp_sa import generate_esp_sa
from ute_ipsec import ute_ipsec

logger = BackgroundLogger.Instance()


class Ipsec(object):
    """ All secgw Ipsec methods in this class"""

    def __init__(self):
        self.cmd_builder = CommandBuilder()
        self.config = ConfigHandler.get_config()
        self.ute_ipsec = ute_ipsec()
        self.secgw_obj = ipsec_secgw()

    def ipsec_config(self, source="both", alias="default"):
        """
        Ipsce config
        :param source can be both,by default it is both  bts or secure_gw from testline_config.json
        :param alais, by default it is "default"
        """
        if source.lower() == "both":
            self.secgw_obj.ipsec_config()
            logger.info("BTS Ipsec config not supported now")
        elif source.lower() == "secure_gw":
            self.secgw_obj.ipsec_config()
        elif source.lower() == "bts":
            logger.info("BTS Ipsec config not supported now")

    def ipsec_enable(self, source="bts", alias="default", device="default"):
        """
        Ipsec Enable
        :param source: host name in testline_config.json in which the ipsec must be enabled
        :param alias : alias, by default it is "default"
        :param device: device, by default it is "default"
        """
        if source.lower() == "secure_gw":
            # """Enables Ipsec on secgw"""
            self.secgw_obj.enable_ipsec_on_secgw(device=device)
        elif source.lower() == "bts":
            # """Stops ipsec on secgw"""
            self.ute_ipsec.enable_ipsec_on_bts(alias)

    def ipsec_disable(self, source="bts", alias="default", device="default"):
        """
        Ipsec disable
        :param source: host name in testline_config.json in which the ipsec must be disabled
        :param alias  : alais, by default it is "default"
        :param device: device, by default it is "default"
        """
        if source.lower() == "secure_gw":
            # """Enables Ipsec on secgw"""
            self.secgw_obj.disable_ipsec_on_secgw(device=device)
        elif source.lower() == "bts":
            # """Stops ipsec on secgw"""
            self.ute_ipsec.disable_ipsec_on_bts(alias)

    def ipsec_get_conf_parameter(self, parameter, connections="all", source="secure_gw",
                                 device="default"):
        """
        Ipsec Get Conf Parameter
        :param parameter: parameter name whose value is needed from ipsec conf file
        :param source : by default source is secure_gw, source must be from testline_config.json
        :param connections:
        :param device:
        :return : parameter value
        """
        paramValue = 0
        conDict = {}
        if source.lower() == "secure_gw":
            connections = self.secgw_obj._interpret_connection_numbers(connections, device)
            for conn in connections:
                awkcommand_template = self.cmd_builder.build_awk_command_to_get_params()
                awkcommand = awkcommand_template.format(conn_num=conn, param=parameter,
                                                        conf_file=get_config_variable(
                                                            [source, "conf_path"]))
                try:
                    result = self.secgw_obj.ipsec_util.execute_command_on_secgw(awkcommand, device)
                    paramValue = result.splitlines()[0].split("=")[1]
                    conDict[conn] = paramValue
                except Exception:
                    pass
        return paramValue

    def ipsec_modify_policy_parameters(self, connections="all", source="secure_gw",
                                       device="default", **parameters):
        """
        Ipsec modify policy parameters
        :param connections:
        :param device:
        :param source: host name in testline_config.json in which the policy parameter needs to
        be changed
        :param parameters  : dictionary of parameter_name:param_value whoese value needs to be
        modify.
        Modifies Ipsec policy parameters for the specified connection(s) with the specified
        parameter name & values on Secgw"""

        if source.lower() == "secure_gw":
            self.secgw_obj.ipsec_util.execute_command_on_secgw('cp {conf_file} {back_file}'.format(
                back_file="/tmp/backup.conf",
                conf_file=get_config_variable(["secgw", "conf_path"])), device)
            connections = self.secgw_obj._interpret_connection_numbers(connections, device)
            for conn in connections:
                for parameter in list(parameters.keys()):
                    self.secgw_obj._edit_ipsec_conf_file(conn, parameter, parameters[parameter],
                                                         device)

            self.secgw_obj.ipsec_secgw_restart()

    def generate_esp_sa_key_file(self, wireshark_host, esp_sa_file='/home/ute/.wireshark/esp_sa',
                                 auth='HMAC-SHA-1-96 [RFC2404]', enc='AES-CBC [RFC3602]'):
        """
        Generate key file for decrypting on wireshark
        :param wiresharkhost: host name in testline_config.json in which the decryption must happen
        :param esp_sa_file : file location
        :param auth : auth protocol used  to decryption
        :param enc : Enc protocol used to decryption
        :return:
        """
        esp_obj = generate_esp_sa()
        esp_obj.generate_esp_sa_key_file(wireshark_host, esp_sa_file, auth, enc)

    def ipsec_verify_status(self, **kwargs):
        """
        :param scf:
        :param kwargs:
        :return:
        """
        scf = kwargs.get('scf')
        if scf:
            ipsec_secgw().ipsec_verify_status_with_scfc(scfc_file=scf)
        # elif kwargs["IKE_list"] and kwargs["ESP_list"] and kwargs["ENC_list"]:
        else:
            self._get_ipsec_status_and_verify(**kwargs)

    def _get_ipsec_status_and_verify(self, **kwargs):
        """
        :param IKE_list: To be passed by user, by default it is none
        :param ESP_list: To be passed by user, by default it is none
        :param ENC_list: To be passed by user, by default it is none
        :return:
        """
        self.fh_interface = False
        self.ike_tunnels = []
        self.esp_tunnels = []
        self.tunnels_not_established = []
        IKE_list_to_validate = []
        ESP_list_to_validate = []
        ENC_protocol_tunnel = []
        tunnel = []
        ipsec_validate_obj = ipsec_validate()

        status_output = self._get_ipsec_status(**kwargs).splitlines()
        logger.debug("Fetched ipsec status {}".format(status_output))
        self._get_tunnels(status_output)
        logger.debug("Fetched IKE tunnel {} and ESP tunnel {}".format(self.ike_tunnels,
                                                                      self.esp_tunnels))
        ipsec_validate_obj.check_for_ike(self.ike_tunnels)
        ipsec_validate_obj.check_for_esp_tunnels(self.esp_tunnels)
        ipsec_validate_obj.check_if_tunnels_not_established(self.tunnels_not_established)

        if self.fh_interface:
            tunnel_profile = kwargs["profile"]
            tunnel_analysis_json = kwargs.pop('tunnel_analysis_file', 'tunnel_analysis.json')
            self.filter_file_content = resource_file.load_json_file(tunnel_analysis_json)
            profile_detail = self.filter_file_content['tunnel_analysis'].get(tunnel_profile)
            ike_list, ips_mapping = self._get_tunnel_profile(profile_detail)
            logger.debug("ike list fetched is {}".format(ike_list))
            ipsec_validate_obj.check_for_ike_esp_list(ike_list, IKE_list_to_validate,
                                                      self.ike_tunnels, self.esp_tunnels,
                                                      ips_mapping)
        else:
            ike_list = kwargs.pop('IKE_list', None)
            esp_list = kwargs.pop('ESP_list', None)
            enc_list = kwargs.pop('ENC_list', None)
            ipsec_validate_obj.check_for_ike_list(ike_list, IKE_list_to_validate, self.ike_tunnels)
            ipsec_validate_obj.check_esp_list(esp_list, ESP_list_to_validate, self.esp_tunnels)
            ipsec_validate_obj.check_enc_list(enc_list, ENC_protocol_tunnel, status_output, tunnel)

    def _get_tunnel_profile(self, tunnel_profile):
        logger.debug("Tunnel profile fetched is {}".format(tunnel_profile))
        ike_tunnel_list = []
        esp_tunnel_list = []
        all_tunnel_ips = {}
        for tunnel in tunnel_profile:
            ike_endpoints = []
            for ike_tunnel in tunnel_profile[tunnel]:
                ike_endpoints.append(ike_tunnel['end_points'])
                ike_endpoints.append(ike_tunnel['should_exist'])
                esp_tunnels = ike_tunnel["esp_tunnels"]
                for esp_tunnel in esp_tunnels:
                    esp_endpoints = []
                    esp_endpoints.append(esp_tunnel['end_points'])
                    esp_endpoints.append(esp_tunnel['should_exist'])
                    esp_tunnel_list.append(esp_endpoints)
                ike_tunnel_list.append(ike_endpoints)
                all_tunnel_ips[ike_tunnel['end_points']] = esp_tunnel_list
        return ike_tunnel_list, all_tunnel_ips

    def _get_ipsec_status(self, **kwargs):
        """Returns ipsec status"""
        source = kwargs.pop("source", "bts")
        device = kwargs.pop("device", "bts")
        command = 'ipsec status'
        try:
            if source.lower() == "secure_gw":
                output, status = ipsec_utils().execute_command_on_secgw('sudo {}'.format(command), device)
            elif source.lower() == "bts":
                output, status = ipsec_utils().execute_command_on_bts('sudo {}'.format(command), device)
            elif source.lower() == "rf_module":
                self.fh_interface = True
                rfmod_inst_id = kwargs['rfmod_inst_id']
                iprange = kwargs.pop('iprange', None)
                output = ipsec_utils().execute_command_on_rf_module('{}'.format(command), device, rfmod_inst_id,
                                                                    iprange)
            else:
                Exception("Source should be either bts or secure_gw or rf_module")
            ipsec_utils().verify_ipsec_status_output(command, output)
            logger.debug(output)
            return output
        except CalledProcessError:
            raise IpSecDisabledError()

    def _get_tunnels(self, status_output):
        regex = r'[0-9]+(?:\.[0-9]+){3}\/(?:32)?(?:\[.*?\])?|[0-9]+(?:\.[0-9]+){3}'
        for line in status_output:
            if "ESTABLISHED" in line:
                matchip = re.findall(regex, line, re.U | re.I)
                if matchip:
                    self.ike_tunnels.append(matchip)
                else:
                    logger.info("Couldn't fetch the ips in Established IKE tunnels")
            if "INSTALLED" in line:
                ip_line = status_output[status_output.index(line) + 1]
                matchip = re.findall(regex, ip_line, re.U | re.I)
                if matchip:
                    self.esp_tunnels.append(matchip)
                else:
                    logger.info("Couldn't fetch the ips in Installed ESP tunnels")
            if "CONNECTING" in line:
                matchip = re.findall(regex, line, re.U | re.I)
                if matchip:
                    self.tunnels_not_established.append(matchip)
                else:
                    logger.info("No ips are in connecting state")
